// src/pages/CustomerRestaurantList.jsx
import React, { useState, useEffect } from 'react';
import { restaurantAPI } from '../../api'; // Import the restaurant API instance

const CustomerRestaurantList = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchRestaurants = async () => {
      try {
        const response = await restaurantAPI.get('/customer/all'); // Endpoint relative to the Restaurant Service's base URL
        setRestaurants(response.data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching restaurants:', error);
        setError('Failed to fetch restaurants.');
        setLoading(false);
      }
    };

    fetchRestaurants();
  }, []);

  if (loading) {
    return <div>Loading restaurants...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  return (
    <div>
  <h1>Explore Restaurants</h1>
  <table>
    <thead>
      <tr>
        <th>Name</th>
        <th>Owner ID</th>
        <th>Address</th>
        <th>Contact</th>
        <th>Availability</th>
        <th>Created At</th>
        <th>Updated At</th>
      </tr>
    </thead>
    <tbody>
      {restaurants.map(restaurant => (
        <tr key={restaurant._id}>
          <td>{restaurant.name}</td>
          <td>{restaurant.ownerId}</td>
          <td>{restaurant.address}</td>
          <td>{restaurant.contactNumber || '-'}</td> {/* Display '-' if no contact number */}
          <td>{restaurant.isAvailable ? 'Open' : 'Closed'}</td>
          <td>{new Date(restaurant.createdAt).toLocaleDateString()}</td>
          <td>{new Date(restaurant.updatedAt).toLocaleDateString()}</td>
          {/* You can add a table data cell with a link if needed */}
          {/* <td><Link to={`/restaurant/${restaurant._id}`}>View Details</Link></td> */}
        </tr>
      ))}
    </tbody>
  </table>
</div>
  );
};

export default CustomerRestaurantList;
